25	float lab_fp16_to_fp32(uint16_t h) {
26	    const uint32_t w = (uint32_t) h << 16;
27	    const uint32_t sign = w & UINT32_C(0x80000000);
28	    const uint32_t two_w = w + w;
29	
30	    const uint32_t exp_offset = UINT32_C(0xE0) << 23;
31	    const float exp_scale = 0x1.0p-112f;
32	    const float normalized_value = fp32_from_bits((two_w >> 4) + exp_offset) * exp_scale;
33	
34	    const uint32_t magic_mask = UINT32_C(126) << 23;
35	    const float magic_bias = 0.5f;
36	    const float denormalized_value = fp32_from_bits((two_w >> 17) | magic_mask) - magic_bias;
37	
38	    const uint32_t denormalized_cutoff = UINT32_C(1) << 27;
39	    const uint32_t result = sign |
40	        (two_w < denormalized_cutoff ? fp32_to_bits(denormalized_value) : fp32_to_bits(normalized_value));
41	    return fp32_from_bits(result);
42	}
