203	// Variant for the vsim/FPGA shootout: vl=64 merges two groups per mask/merge
204	// (fewer instructions) at the price of slideup/slidedown data movement. QEMU
205	// charges per element and prefers vl512; real hardware may prefer this one.
206	NOINLINE void ggml_vec_dot_q1_0_q8_0_vl512w(const int n, float * GGML_RESTRICT s, const void * GGML_RESTRICT vx, const void * GGML_RESTRICT vy) {
207	    const int qk = QK1_0;
208	    const int nb = n / qk;
209	    assert(n % qk == 0);
210	
211	    const block_q1_0 * GGML_RESTRICT x = vx;
