220	    vfloat32m2_t facc = __riscv_vfmv_v_f_f32m2(0.0f, 4);
221	
222	    for (int ib = 0; ib < nb; ++ib) {
223	        const float d0 = GGML_CPU_FP16_TO_FP32(x[ib].d);
224	        const block_q8_0 * GGML_RESTRICT yb = &y[ib * 4];
225	
226	        const vint8m1_t q0 = __riscv_vle8_v_i8m1(yb[0].qs, 32);
227	        const vint8m1_t q1 = __riscv_vle8_v_i8m1(yb[1].qs, 32);
228	        const vint8m1_t q2 = __riscv_vle8_v_i8m1(yb[2].qs, 32);
229	        const vint8m1_t q3 = __riscv_vle8_v_i8m1(yb[3].qs, 32);
230	
231	        const vbool8_t m01 = __riscv_vlm_v_b8(x[ib].qs, 64);
232	        const vbool8_t m23 = __riscv_vlm_v_b8(x[ib].qs + 8, 64);
233	        const vint8m1_t q01 = __riscv_vslideup_vx_i8m1(q0, q1, 32, 64);
234	        const vint8m1_t q23 = __riscv_vslideup_vx_i8m1(q2, q3, 32, 64);
235	        const vint8m1_t s01 = __riscv_vmerge_vvm_i8m1(__riscv_vneg_v_i8m1(q01, 64), q01, m01, 64);
236	        const vint8m1_t s23 = __riscv_vmerge_vvm_i8m1(__riscv_vneg_v_i8m1(q23, 64), q23, m23, 64);
237	
238	        const vint8m1_t s1h = __riscv_vslidedown_vx_i8m1(s01, 32, 32);
239	        const vint8m1_t s3h = __riscv_vslidedown_vx_i8m1(s23, 32, 32);
240	        vint16m1_t gs       = __riscv_vwredsum_vs_i8m1_i16m1(s01, zero, 32);
241	        const vint16m1_t r1 = __riscv_vwredsum_vs_i8m1_i16m1(s1h, zero, 32);
242	        const vint16m1_t r2 = __riscv_vwredsum_vs_i8m1_i16m1(s23, zero, 32);
243	        const vint16m1_t r3 = __riscv_vwredsum_vs_i8m1_i16m1(s3h, zero, 32);
244	
