246	        // all slideups run at vl=4: lanes above each offset are overwritten by
247	        // the later slideups, so only lane `offset` of each survives
248	        gs = __riscv_vslideup_vx_i16m1(gs, r1, 1, 4);
249	        gs = __riscv_vslideup_vx_i16m1(gs, r2, 2, 4);
250	        gs = __riscv_vslideup_vx_i16m1(gs, r3, 3, 4);
251	        const vint32m2_t gs32 = __riscv_vsext_vf2_i32m2(gs, 4);
252	        const vfloat32m2_t dyf = lab_expand_fp16_x4((const uint16_t *)&yb[0].d, sizeof(block_q8_0));
253	
254	        // facc += d0 * (dy .* group_sums)
255	        const vfloat32m2_t gsf = __riscv_vfcvt_f_x_v_f32m2(gs32, 4);
256	        facc = __riscv_vfmacc_vf_f32m2(facc, d0, __riscv_vfmul_vv_f32m2(gsf, dyf, 4), 4);
257	    }
258	
259	    // ordered reduction: deterministic across implementations
260	    const vfloat32m1_t red = __riscv_vfredosum_vs_f32m2_f32m1(facc, __riscv_vfmv_v_f_f32m1(0.0f, 1), 4);
