264	NOINLINE void ggml_vec_dot_q1_0_q8_0_vl256(const int n, float * GGML_RESTRICT s, const void * GGML_RESTRICT vx, const void * GGML_RESTRICT vy) {
265	    const int qk = QK1_0;
266	    const int nb = n / qk;
267	    assert(n % qk == 0);
268	
269	    const block_q1_0 * GGML_RESTRICT x = vx;
270	    const block_q8_0 * GGML_RESTRICT y = vy;
271	
272	    //LMUL = 1, VLMAX = 32
273	    const size_t vl32 = __riscv_vsetvl_e8m1(32);
274	    assert(vl32 == 32);
275	
276	    const vint16m1_t zero = __riscv_vmv_v_x_i16m1(0, 1);
277	
278	    float sumf = 0;
279	
280	    for (int ib = 0; ib < nb; ++ib) {
281	        const float d0 = GGML_CPU_FP16_TO_FP32(x[ib].d);
282	
283	        float acc = 0;
284	
285	        for (int k = 0; k < 4; ++k) {
286	            const block_q8_0 * GGML_RESTRICT yb = &y[ib * 4 + k];
